int main() {
    string tmp;
    int last = -1;
    // 记录位置幼儿和班级的映射, map会自动进行排序的
    map<int, int> mp;
    int count = 0;
    while (cin >> tmp) {
        if (tmp == ""){
            break;
        }
        count++;
        vector<string> ans = split(tmp, '/');
        int id = stoi(ans[0]);
        // 输入数据合法性判断
        if (id <= 0 || id > 999 || count > 999) {
            cout << "ERROR";
            return 0;
        }
        // 处理关系
        if (last == -1) {
            mp[id] = 0;
        } else {
            if (ans[1] == "N") {
                mp[id] = !mp[last];
            } else {
                mp[id] = mp[last];
            }
        }
        last = id;
    }

    int classId  = -1;
    for (int i = 0; i < 2; i++) {
        bool flag =false;
        for (const auto& pair : mp) {
            int first = pair.first;
            int second = pair.second;
            if (!flag) {
                flag = true;
                if (classId == -1) {
                    classId = second;
                } else {
                    classId = !classId;
                }
            }
            if (second == classId) {
                cout << first << " ";
            }
        }
        cout << endl;
