const rl = readline.createInterface({
    input: process.stdin,
    output: process.stdout
});
​
const mp = new Map(); // 用 Map 记录关系
let last = -1;
​
rl.on("line", (line) => {
    let inputs = line.trim().split(/\s+/); // 按空格分割输入
    let count = 0;
    for (let tmp of inputs) {
        let [id, relation] = tmp.split("/");
        id = parseInt(id);
        count += 1;
        // 输入数据合法性检查
        if (id <= 0 || id > 999 || count > 999) {
            console.log("ERROR");
            process.exit();
        }
​
        // 处理关系
        if (last === -1) {
            mp.set(id, 0);
        } else {
            if (relation === "N") {
                mp.set(id, 1 - mp.get(last));
            } else {
                mp.set(id, mp.get(last));
            }
        }
        last = id;
    }
​
    let sortedKeys = Array.from(mp.keys()).sort((a, b) => a - b);
    let classId = -1;

    for (let i = 0; i < 2; i++) {
        let flag = false;
        let result = [];
        for (let key of sortedKeys) {
            if (!flag) {
                flag = true;
                classId = classId === -1 ? mp.get(key) : 1 - classId;
            }
            if (mp.get(key) === classId) {
                result.push(key);
            }
        }
        console.log(result.join(" "));
    }
    process.exit();
});
