import (
    "bufio"
    "fmt"
    "os"
    "sort"
    "strings"
    "strconv"
)
​
func main() {
    scanner := bufio.NewScanner(os.Stdin)
    mp := make(map[int]int) // 记录幼儿与班级的映射
    var ids []int           // 记录所有 id
    last := -1
    count := 0
    // 读取输入
    if scanner.Scan() {
        inputs := strings.Fields(scanner.Text()) // 按空格分割
        for _, tmp := range inputs {
            parts := strings.Split(tmp, "/")
            id, _ := strconv.Atoi(parts[0])
            count += 1
            // 输入数据合法性检查
            if id <= 0 || id > 999 || count > 999 {
                fmt.Println("ERROR")
                return
            }
​
            // 处理关系
            if last == -1 {
                mp[id] = 0
            } else {
                if parts[1] == "N" {
                    mp[id] = 1 - mp[last]
                } else {
                    mp[id] = mp[last]
                }
            }
            ids = append(ids, id)
            last = id
        }
    }
​
    // 按 ID 排序
    sort.Ints(ids)
    classId := -1
​
    // 输出结果
    for i := 0; i < 2; i++ {
        flag := false
        var result []string
        for _, id := range ids {
            if !flag {
                flag = true
                if classId == -1 {
                    classId = mp[id]
                } else {
                    classId = 1 - classId
                }
            }
            if mp[id] == classId {
                result = append(result, strconv.Itoa(id))
            }
        }
        fmt.Println(strings.Join(result, " "))
    }
}
